corrected_code:
const express = require('express');
const router = express.Router();
const admin = require('firebase-admin');
const { DeviceToken } = require('../models');

router.post('/api/devices/:deviceId/send-test-alert', authenticateSession, async (req, res) => {
  const { deviceId } = req.params;
  const { title, message } = req.body;

  const device = await DeviceToken.findOne({
    where: { id: deviceId, userId: req.session.userId }
  });
  if (!device) {
    return res.status(403).json({ error: 'Device not found or unauthorized' });
  }

  await admin.messaging().send({
    token: device.fcmToken,
    notification: { title: title || 'Test Alert', body: message || 'Notification test' }
  });

  return res.json({ status: 'sent', deviceId });
});
